export function getRussianItemName(filename) {
    if (!filename) return 'Слой';
    const clean = filename.replace(/\.png$/i, '').toLowerCase();
    const item = MINECRAFT_ITEMS.find(i => i.file === filename || i.id === clean || i.id === filename);
    if (item && item.name) {
        return item.name;
    }
    const readable = clean.replace(/_/g, ' ');
    return readable.charAt(0).toUpperCase() + readable.slice(1);
}

